import{_ as t,o as a,c as o,ai as r}from"./chunks/framework.Cabe_Szf.js";const c=JSON.parse('{"title":"Prompt X-ray","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/xray.md","filePath":"en/guide/xray.md","lastUpdated":1792109577000}'),s={name:"en/guide/xray.md"};function h(n,e,i,p,l,d){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="prompt-x-ray" tabindex="-1">Prompt X-ray <a class="header-anchor" href="#prompt-x-ray" aria-label="Permalink to &quot;Prompt X-ray&quot;">​</a></h1><p>The <strong>Prompt X-ray</strong> draws each turn&#39;s prompt to scale and says, part by part, what it was and what happened to it: already in the model&#39;s memory, read again, or cut by the daemon and never seen.</p><p><strong>Sidebar item:</strong> Prompt X-ray (below Live) <strong>Route:</strong> <code>/xray</code><strong>Added in:</strong> v0.8.0 (October 2026) <strong>Requires:</strong> turns on the Live page. The X-ray reads what the observe port recorded; point a tool at <code>http://localhost:11435</code> and send a few messages.</p><h2 id="what-s-the-point" tabindex="-1">What&#39;s the point? <a class="header-anchor" href="#what-s-the-point" aria-label="Permalink to &quot;What&#39;s the point?&quot;">​</a></h2><p>Three things go wrong with a prompt on a local model, and none of them is visible from inside the tool that sent it.</p><ul><li>The prompt stops matching the previous turn somewhere near the start, so the model reads everything after that point again. A timestamp in the system prompt does this on every turn.</li><li>Tool schemas get switched on and take a fixed slice of every prompt from then on.</li><li>The prompt outgrows the context, and Ollama keeps the first few tokens and the end, drops the middle, and answers as if nothing was wrong. The system prompt is usually in what was dropped.</li></ul><p>The X-ray shows all three as a picture of the prompt itself.</p><h2 id="reading-the-chart" tabindex="-1">Reading the chart <a class="header-anchor" href="#reading-the-chart" aria-label="Permalink to &quot;Reading the chart&quot;">​</a></h2><p>One bar per turn, left to right in tokens as the daemon counted them. The widest prompt in the conversation sets the scale.</p><p><strong>Colour is what the part is:</strong> system prompt, tool schemas, earlier turns, the new message, in the order the daemon reads them.</p><p><strong>Brightness is what happened to it:</strong></p><ul><li><strong>Dim</strong>: already in the model&#39;s memory from the previous turn. Cost nothing.</li><li><strong>Bright</strong>: read again this turn.</li><li><strong>Striped, with a line through it</strong>: cut by the daemon. The model never saw it.</li></ul><p>A hairline gap separates the parts, so a bar reads as a structure at a glance. The right-hand column gives the prompt reading time and the share that was in memory.</p><p>Under a bar, a note appears only when something happened:</p><ul><li>the first turn from this tool with this model;</li><li>the model was loaded again, so nothing was in memory and the prompt is not at fault;</li><li>the prompt stopped matching the previous turn, with the part it fell in and the token position, which is an estimate from characters;</li><li>tools were switched on, with how many tokens of schemas now sit in every prompt;</li><li>the prompt outgrew the context, with how many tokens were dropped and whether the system prompt and the tool schemas were among them.</li></ul><h2 id="clicking-a-part" tabindex="-1">Clicking a part <a class="header-anchor" href="#clicking-a-part" aria-label="Permalink to &quot;Clicking a part&quot;">​</a></h2><p>Click any segment and that turn&#39;s request opens below, through the same request viewer as the Live page, with the part you clicked first. The viewer marks the position where the prompt stopped matching the previous one inside the actual text.</p><p>The request text is kept only when <strong>Keep the prompt text</strong> is switched on on the Live page. Without it, the sizes are exact and the text is not available; the page says so.</p><h2 id="the-totals" tabindex="-1">The totals <a class="header-anchor" href="#the-totals" aria-label="Permalink to &quot;The totals&quot;">​</a></h2><p>Under the chart, one sentence: how long the prompt reading took over the conversation, how much of that a stable prompt would have skipped, and how many turns answered a prompt that was not fully sent.</p><p>The saving is an estimate. It assumes prompt reading time grows with the number of uncached tokens, which it does to a good approximation.</p><h2 id="what-the-page-does-not-know" tabindex="-1">What the page does not know <a class="header-anchor" href="#what-the-page-does-not-know" aria-label="Permalink to &quot;What the page does not know&quot;">​</a></h2><p>The model&#39;s own tokenizer. The widths are the daemon&#39;s token counts; where a bar is split into parts, the split is scaled from characters. The striped part is sized from the difference between what was sent and what the daemon counted. Every estimate on the page is labelled as one.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live.html">Live</a> records the turns the X-ray draws.</li><li><a href="./cache-lab.html">Cache Lab</a> measures what fixing a cache break saves, on your own daemon.</li><li><a href="./shared-box.html">Shared box</a> shows what each tool&#39;s settings cost the other tools.</li></ul>',25)])])}const g=t(s,[["render",h]]);export{c as __pageData,g as default};
